    counts = Counter()
    for row in grid:
        for x in row:
            counts[x] += 1
    bg = counts.most_common(1)[0][0]

    # Find red line
    red_row = None
    for r in range(rows):
        if all(grid[r][c] == 2 for c in range(cols)):
            red_row = r
            break

    red_col = None
