        for c in range(cols):
            if all(grid[r][c] == 2 for r in range(rows)):
                red_col = c
                break

    if red_row is None and red_col is None:
        return grid

    # Find special colors (non-bg, non-2)
    special_colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and grid[r][c] != 2:
                special_colors.add(grid[r][c])

    if not special_colors:
        return grid

    special_val = list(special_colors)[0]

    output = [[bg for _ in range(cols)] for _ in range(rows)]

    if red_row is not None:
